"""ROS-independent state logic for the 13-section driving course."""

from dataclasses import dataclass


LEFT, STRAIGHT, RIGHT = -1, 0, 1
CAMERA, NAV2 = 1, 2
INTERSECTIONS = {4, 6, 8, 11}
NAV2_SECTIONS = {7, 10}


@dataclass
class MissionInput:
    section: int = 1
    now: float = 0.0
    pitch_deg: float = 0.0
    imu_valid: bool = False
    stop_detected: bool = False
    stop_distance_m: float = float("inf")
    stop_distance_valid: bool = False
    traffic_green: bool = False
    traffic20_detected: bool = False
    gps_direction: int = STRAIGHT
    camera_path_valid: bool = False
    camera_steering_deg: float = 0.0
    nav2_valid: bool = False
    nav2_stage: int = 0
    nav2_steering_deg: float = 0.0
    yellow_distance_m: float = float("inf")
    yellow_distance_valid: bool = False
    yellow_side: int = 0  # -1 left image side, +1 right image side


@dataclass
class MissionOutput:
    stage: int
    steering_deg: float
    control_mode: int
    turn_direction: int
    status: str


class CourseMission:
    def __init__(self, ramp_pitch_deg=10.0, ramp_delay_sec=2.0,
                 stop_distance_m=0.5, minimum_stop_sec=0.5):
        self.ramp_pitch_deg = float(ramp_pitch_deg)
        self.ramp_delay_sec = float(ramp_delay_sec)
        self.stop_distance_m = float(stop_distance_m)
        self.minimum_stop_sec = float(minimum_stop_sec)
        self.section = None
        self.ramp_trigger_time = None
        self.intersection_stop_time = None
        self.intersection_released = False
        self.final_stopped = False
        self.traffic20_previous = False
        self.traffic20_count = 0
        self.yellow_avoid_active = False
        self.yellow_stop_time = None

    def enter_section(self, section):
        if section == self.section:
            return
        self.section = section
        self.ramp_trigger_time = None
        self.intersection_stop_time = None
        self.intersection_released = False
        self.traffic20_previous = False
        if section == 9:
            self.traffic20_count = 0
        if section != 13:
            self.final_stopped = False

    @staticmethod
    def stopped(status, mode=CAMERA, direction=STRAIGHT):
        return MissionOutput(0, 0.0, mode, direction, status)

    def update(self, data):
        self.enter_section(int(data.section))
        section = self.section
        direction = data.gps_direction if data.gps_direction in (LEFT, STRAIGHT, RIGHT) else STRAIGHT

        if section in NAV2_SECTIONS:
            if not data.nav2_valid:
                return self.stopped("SAFE_STOP:NAV2_INVALID", NAV2, direction)
            limit = 1 if section == 10 else 2
            stage = max(0, min(limit, int(data.nav2_stage)))
            return MissionOutput(stage, data.nav2_steering_deg, NAV2, direction,
                                 "PARALLEL_PARKING_NAV2" if section == 10 else "T_COURSE_NAV2")

        if data.yellow_distance_valid and data.yellow_distance_m <= 0.3:
            if not self.yellow_avoid_active:
                self.yellow_avoid_active = True
                self.yellow_stop_time = data.now
        if self.yellow_avoid_active:
            if not data.yellow_distance_valid:
                return self.stopped("YELLOW_AVOID:DEPTH_INVALID", CAMERA, direction)
            if data.yellow_distance_m >= 0.5:
                self.yellow_avoid_active = False
                self.yellow_stop_time = None
            elif data.now - self.yellow_stop_time < 0.5:
                return self.stopped("YELLOW_AVOID:STOP", CAMERA, direction)
            else:
                # Positive steering is left; move away from the detected image side.
                steering = -15.0 if data.yellow_side < 0 else 15.0
                return MissionOutput(1, steering, CAMERA, direction, "YELLOW_AVOID:MOVE_AWAY")

        if not data.camera_path_valid:
            return self.stopped("SAFE_STOP:CAMERA_PATH_INVALID", CAMERA, direction)

        if section == 2:
            trigger = data.imu_valid and data.pitch_deg >= self.ramp_pitch_deg and data.stop_detected
            if trigger and self.ramp_trigger_time is None:
                self.ramp_trigger_time = data.now
            stage = 1 if (self.ramp_trigger_time is not None and
                          data.now - self.ramp_trigger_time >= self.ramp_delay_sec) else 2
            status = "RAMP_STAGE_1" if stage == 1 else "RAMP_DELAY_STAGE_2"
            return MissionOutput(stage, data.camera_steering_deg, CAMERA, direction, status)

        if section in INTERSECTIONS:
            at_line = (data.stop_distance_valid and
                       data.stop_distance_m <= self.stop_distance_m)
            if at_line and self.intersection_stop_time is None:
                self.intersection_stop_time = data.now
            if self.intersection_stop_time is not None and not self.intersection_released:
                stopped_long_enough = data.now - self.intersection_stop_time >= self.minimum_stop_sec
                if stopped_long_enough and data.traffic_green:
                    self.intersection_released = True
                else:
                    return self.stopped("INTERSECTION_WAIT_GREEN", CAMERA, direction)
            return MissionOutput(2, data.camera_steering_deg, CAMERA, direction,
                                 "INTERSECTION_GO")

        if section == 9:
            rising = data.traffic20_detected and not self.traffic20_previous
            self.traffic20_previous = data.traffic20_detected
            if rising:
                self.traffic20_count += 1
            stage = 3 if self.traffic20_count == 1 else 2
            return MissionOutput(stage, data.camera_steering_deg, CAMERA, direction,
                                 f"TRAFFIC20_COUNT_{self.traffic20_count}")

        if section == 13:
            at_line = (data.stop_distance_valid and
                       data.stop_distance_m <= self.stop_distance_m)
            self.final_stopped = self.final_stopped or at_line
            if self.final_stopped:
                return self.stopped("FINISH_STOPPED", CAMERA, direction)
            return MissionOutput(2, data.camera_steering_deg, CAMERA, direction,
                                 "FINISH_APPROACH")

        names = {1: "START", 3: "CURVE_CENTERING", 5: "WALL_AVOIDANCE",
                 12: "SHARP_CURVE"}
        return MissionOutput(2, data.camera_steering_deg, CAMERA, direction,
                             names.get(section, "CAMERA_CENTERING"))
